{"source":"#include <stdio.h>
#include <math.h>

int main(int argc, char *argv[])
{
    long long int n, i, sum;
    scanf("%lld", &n);
    long long int sq=sqrt(n);
    if(sq*sq==n)
    {
        printf("-1\n");
        return 0;
    }

    for(i=sq; i>=1; i--)
    {
        long long int temp=i;
        sum=0;
        while(temp)
        {
            sum+=temp%10;
            temp/=10;
        }
        if(i*i + i*sum == n)
        {
            printf("%lld\n", i);
            return 0;
        }
    }
    printf("-1\n");
    return 0;
}"}
